draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // draw stick figure meditating
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // draw journal
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 50, H/2 + 120, 100, 50);
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(W/2 - 45, H/2 + 125, 90, 40);

  // animate stick figure's head
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 10, H/2 + 20 + Math.cos(t) * 10, 20, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
